package com.sam.booksmk;

import android.app.*;
import android.os.*;
import android.graphics.*;
import android.graphics.pdf.PdfRenderer;
import android.net.Uri;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import android.view.*;
import android.widget.*;
import android.provider.OpenableColumns;
import android.webkit.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.zip.*;

public class MainActivity extends Activity {
  final int GOLD=Color.rgb(215,169,67), BG=Color.rgb(8,8,8), PANEL=Color.rgb(20,20,20);
  LinearLayout root, list; SQLiteDatabase db; TextView status; Uri pdfUri; PdfRenderer renderer; PdfRenderer.Page pdfPage; ParcelFileDescriptor pdfFd; int page=0;
  final Activity self=this;
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);openDb();home();}
  void openDb(){File f=new File(getFilesDir(),"booksmk.db");db=SQLiteDatabase.openOrCreateDatabase(f,null);db.execSQL("CREATE TABLE IF NOT EXISTS books(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,uri TEXT NOT NULL,type TEXT NOT NULL,added INTEGER,progress INTEGER DEFAULT 0,favorite INTEGER DEFAULT 0)");}
  TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(14,12,14,12);return t;}
  Button btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(GOLD);b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(PANEL));b.setOnClickListener(v->r.run());return b;}
  void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);root.setPadding(16,12,16,8);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);scroll.addView(root);LinearLayout shell=new LinearLayout(this);shell.setOrientation(1);TextView brand=text("booksmk  |  مكتبتك الذهبية",25,GOLD);brand.setGravity(Gravity.CENTER);shell.addView(brand);shell.addView(text(title,21,Color.WHITE));root.addView(shell);setContentView(scroll);}
  void home(){base("مكتبتك الخاصة");root.addView(text("كتبك وقراءتك محفوظة على هذا الجهاز. لا حسابات ولا إعلانات ولا اتصال بالإنترنت.",14,0xffb9b1a3));root.addView(btn("＋ استيراد كتاب PDF أو EPUB أو TXT",()->pickBook()));root.addView(btn("نسخ احتياطي للمكتبة",()->backup()));root.addView(btn("استعادة نسخة احتياطية",()->restore()));root.addView(text("مكتبتي",20,GOLD));Cursor c=db.rawQuery("SELECT id,title,type,favorite,progress FROM books ORDER BY added DESC",null);if(c.getCount()==0)root.addView(text("لم تضف كتباً بعد. استورد كتاباً من جهازك للبدء.",15,0xffb9b1a3));while(c.moveToNext()){final int id=c.getInt(0);String title=c.getString(1),type=c.getString(2);int fav=c.getInt(3);LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setPadding(4,8,4,8);row.addView(text("▤  "+title+"  ·  "+type.toUpperCase(Locale.ROOT),17,Color.WHITE));LinearLayout actions=new LinearLayout(this);actions.addView(btn("قراءة",()->openBook(id)));actions.addView(btn(fav==1?"★":"☆",()->{db.execSQL("UPDATE books SET favorite=? WHERE id=?",new Object[]{fav==1?0:1,id});home();}));actions.addView(btn("حذف",()->new AlertDialog.Builder(this).setMessage("حذف الكتاب من المكتبة؟ لن يحذف الملف الأصلي.").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(d,w)->{db.delete("books","id=?",new String[]{String.valueOf(id)});home();}).show()));row.addView(actions);root.addView(row);View line=new View(this);line.setBackgroundColor(0xff55431e);root.addView(line,new LinearLayout.LayoutParams(-1,1));}c.close();root.addView(btn("المفضلة فقط",()->favorites()));root.addView(btn("معلومات التطبيق",()->new AlertDialog.Builder(this).setTitle("booksmk").setMessage("مكتبة عربية محلية — إصدار أولي. ملفاتك تبقى على جهازك.").setPositiveButton("حسنًا",null).show()));}
  void pickBook(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","application/epub+zip","text/plain","application/octet-stream"});startActivityForResult(i,10);}
  String nameOf(Uri u){String n="كتاب";try(Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst()){int x=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(x>=0)n=c.getString(x);}}return n;}
  @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(res!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();try{
    if(req==11){try(OutputStream out=getContentResolver().openOutputStream(u)){if(out==null)throw new IOException("تعذر فتح ملف النسخة");out.write(pendingBackup.getBytes(java.nio.charset.StandardCharsets.UTF_8));toast("تم حفظ النسخة الاحتياطية.");}return;}
    if(req==12){try(InputStream in=getContentResolver().openInputStream(u)){if(in==null)throw new IOException("تعذر قراءة الملف");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);JSONObject json=new JSONObject(new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));if(!"booksmk".equals(json.optString("app"))||json.optInt("version")!=1)throw new IOException("ملف نسخة booksmk غير صالح");JSONArray arr=json.getJSONArray("books");db.beginTransaction();try{db.delete("books",null,null);for(int x=0;x<arr.length();x++){JSONObject o=arr.getJSONObject(x);ContentValues v=new ContentValues();v.put("title",o.getString("title"));v.put("uri",o.getString("uri"));v.put("type",o.getString("type"));v.put("added",o.optLong("added",System.currentTimeMillis()));v.put("progress",o.optInt("progress",0));v.put("favorite",o.optInt("favorite",0));db.insertOrThrow("books",null,v);}db.setTransactionSuccessful();}finally{db.endTransaction();}toast("تمت استعادة بيانات المكتبة. قد تحتاج إلى إعادة اختيار الملفات إذا تغيرت صلاحياتها.");home();}return;}
    if(req==10){try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}String name=nameOf(u),ext=name.toLowerCase(Locale.ROOT);String type=ext.endsWith(".pdf")?"pdf":ext.endsWith(".epub")?"epub":"txt";ContentValues v=new ContentValues();v.put("title",name.replaceFirst("(?i)\\.(pdf|epub|txt|md)$",""));v.put("uri",u.toString());v.put("type",type);v.put("added",System.currentTimeMillis());db.insert("books",null,v);home();}
  }catch(Exception e){toast("تعذر إكمال العملية: "+e.getMessage());}}
  void openBook(int id){Cursor c=db.rawQuery("SELECT title,uri,type FROM books WHERE id=?",new String[]{String.valueOf(id)});if(!c.moveToFirst()){c.close();return;}String title=c.getString(0);Uri uri=Uri.parse(c.getString(1));String type=c.getString(2);c.close();if(type.equals("pdf")){openPdf(title,uri,id);return;}if(type.equals("epub")){openEpub(title,uri,id);return;}try(InputStream in=getContentResolver().openInputStream(uri)){byte[] buf=new byte[8192];ByteArrayOutputStream out=new ByteArrayOutputStream();int n;while((n=in.read(buf))>0)out.write(buf,0,n);showText(title,new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8),id);}catch(Exception e){toast("تعذر فتح الملف: "+e.getMessage());}}
  void showText(String title,String content,int id){base(title);TextView body=text(content,19,0xffeee7db);body.setGravity(Gravity.TOP|Gravity.RIGHT);body.setTextIsSelectable(true);root.addView(body);root.addView(btn("العودة للمكتبة",()->home()));}
  void openEpub(String title,Uri uri,int id){try{InputStream in=getContentResolver().openInputStream(uri);ZipInputStream zip=new ZipInputStream(in);String html=null;ByteArrayOutputStream out=new ByteArrayOutputStream();ZipEntry e;while((e=zip.getNextEntry())!=null){String n=e.getName().toLowerCase(Locale.ROOT);if(!e.isDirectory()&&(n.endsWith(".xhtml")||n.endsWith(".html")||n.endsWith(".htm"))){out.reset();byte[] b=new byte[8192];int k;while((k=zip.read(b))>0)out.write(b,0,k);html=new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);break;}}zip.close();if(html==null){toast("لم أجد فصلاً قابلاً للقراءة داخل EPUB.");return;}base(title);WebView w=new WebView(this);w.setBackgroundColor(BG);w.getSettings().setJavaScriptEnabled(false);w.loadDataWithBaseURL(null,"<html dir='rtl'><meta charset='utf-8'><body style='background:#080808;color:#eee7db;font:20px sans-serif;line-height:2;padding:18px;text-align:right'>"+html+"</body></html>","text/html","UTF-8",null);root.addView(w,new LinearLayout.LayoutParams(-1,0,1));root.addView(btn("العودة للمكتبة",()->home()));}catch(Exception e){toast("تعذر فتح EPUB: "+e.getMessage());}}
  void openPdf(String title,Uri uri,int id){try{pdfFd=getContentResolver().openFileDescriptor(uri,"r");renderer=new PdfRenderer(pdfFd);page=0;showPdf(title);}catch(Exception e){toast("تعذر فتح PDF: "+e.getMessage());}}
  void showPdf(String title){base(title+" · PDF");LinearLayout controls=new LinearLayout(this);controls.addView(btn("السابق",()->{if(page>0){page--;showPdf(title);}}));controls.addView(btn("التالي",()->{if(renderer!=null&&page<renderer.getPageCount()-1){page++;showPdf(title);}}));controls.addView(text((page+1)+" / "+renderer.getPageCount(),14,GOLD));root.addView(controls);if(pdfPage!=null){pdfPage.close();pdfPage=null;}pdfPage=renderer.openPage(page);Bitmap bitmap=Bitmap.createBitmap(pdfPage.getWidth(),pdfPage.getHeight(),Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);pdfPage.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);ScrollView sc=new ScrollView(this);sc.addView(image);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));root.addView(btn("العودة للمكتبة",()->home()));}
  void favorites(){base("المفضلة");Cursor c=db.rawQuery("SELECT title FROM books WHERE favorite=1",null);if(c.getCount()==0)root.addView(text("لا توجد كتب مفضلة بعد.",16,Color.WHITE));while(c.moveToNext())root.addView(text("★  "+c.getString(0),17,GOLD));c.close();root.addView(btn("العودة",()->home()));}
  void backup(){try{JSONArray a=new JSONArray();Cursor c=db.rawQuery("SELECT title,uri,type,added,progress,favorite FROM books",null);while(c.moveToNext()){JSONObject o=new JSONObject();o.put("title",c.getString(0));o.put("uri",c.getString(1));o.put("type",c.getString(2));o.put("added",c.getLong(3));o.put("progress",c.getInt(4));o.put("favorite",c.getInt(5));a.put(o);}c.close();JSONObject rootJson=new JSONObject();rootJson.put("app","booksmk");rootJson.put("version",1);rootJson.put("books",a);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"booksmk-backup.json");pendingBackup=rootJson.toString(2);startActivityForResult(i,11);}catch(Exception e){toast("تعذر تجهيز النسخة الاحتياطية.");}}
  String pendingBackup="";
  void restore(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");startActivityForResult(i,12);}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
  @Override protected void onDestroy(){super.onDestroy();try{if(pdfPage!=null)pdfPage.close();if(renderer!=null)renderer.close();if(pdfFd!=null)pdfFd.close();}catch(Exception ignored){}}
}
